// GameSwitcher.js — Universal in-game & hub game-switching dock.
//
// Enables instant 1-click swapping between any of the 5 Dweebs games (Brawler,
// Expedition, Escape, Mimic, Warfare), returning to Dweeb's Hub, or navigating
// to Omnexx, Stickshot, or the Yaeger Main Portal without getting stuck.

import { el } from './dom.js';

export const MODES = [
  { id: 'hub', name: "Dweeb's Hub", icon: '🏰', blurb: '3D Battle Diorama' },
  { id: 'brawler', name: 'Knockout Brawl', icon: '🥊', blurb: '4-Player Arena' },
  { id: 'adventure', name: 'Expedition & Dynasty', icon: '🌱', blurb: 'Meadowlands Civ Sim' },
  { id: 'escape', name: 'Escape Rooms', icon: '🧩', blurb: 'Physics Puzzle Island' },
  { id: 'mimic', name: 'Mimic & Mutate', icon: '🐒', blurb: '1st-Person Toy Lab' },
  { id: 'warfare', name: 'Dweeb Warfare', icon: '⚔️', blurb: 'RTS Toy Army (Co-op/Versus)' },
];

export function createGameSwitcher({ router } = {}) {
  let activeMode = 'hub';
  let isOpen = false;

  const node = el(`
    <aside id="dweebs-game-switcher" class="game-switcher-dock" aria-label="Game Switcher">
      <button id="switcher-toggle-btn" class="switcher-toggle" aria-haspopup="true" aria-expanded="false" title="Switch Game or Return to Hub (Press G)">
        <span class="switcher-icon" id="switcher-icon">🏰</span>
        <span class="switcher-title" id="switcher-label">Dweeb's Hub</span>
        <span class="switcher-caret">▾</span>
      </button>

      <div id="switcher-menu" class="switcher-dropdown hidden" role="menu">
        <div class="switcher-header">SWITCH PLAYGROUND</div>
        <div class="switcher-list">
          ${MODES.map(m => `
            <button class="switcher-item ${m.id === 'hub' ? 'active' : ''}" data-mode="${m.id}" role="menuitem">
              <span class="si-icon">${m.icon}</span>
              <div class="si-text">
                <span class="si-title">${m.name}</span>
                <span class="si-desc">${m.blurb}</span>
              </div>
            </button>
          `).join('')}
        </div>

        <div class="switcher-section-title">GLOBAL PORTALS</div>
        <div class="switcher-portals">
          <a href="../" class="switcher-portal-link" title="Yaeger Complex Landing">
            <span>🚪</span> Main Portal (All Apps)
          </a>
          <a href="../omnexx/" class="switcher-portal-link" title="Enter Omnexx">
            <span>🌀</span> Omnexx Portal
          </a>
          <a href="../stickshot/" class="switcher-portal-link" title="Play Stickshot Arcade">
            <span>🎯</span> Stickshot Range
          </a>
        </div>
      </div>
    </aside>
  `);

  document.body.appendChild(node);

  const toggleBtn = node.querySelector('#switcher-toggle-btn');
  const menu = node.querySelector('#switcher-menu');
  const icon = node.querySelector('#switcher-icon');
  const label = node.querySelector('#switcher-label');

  function setOpen(open) {
    isOpen = open;
    toggleBtn.setAttribute('aria-expanded', String(isOpen));
    menu.classList.toggle('hidden', !isOpen);
    toggleBtn.classList.toggle('active', isOpen);
  }

  function setMode(modeId) {
    activeMode = modeId;
    const def = MODES.find(m => m.id === modeId) || MODES[0];
    icon.textContent = def.icon;
    label.textContent = def.name;
    for (const b of menu.querySelectorAll('.switcher-item')) {
      b.classList.toggle('active', b.dataset.mode === modeId);
    }
  }

  function executeSwitch(targetMode) {
    setOpen(false);

    if (document.pointerLockElement) {
      document.exitPointerLock?.();
    }

    if (targetMode === 'hub') {
      setMode('hub');
      if (window.__dweebsToMenu) {
        window.__dweebsToMenu();
      } else {
        router?.setMatchLock(false);
        router?.go('/');
      }
      return;
    }

    setMode(targetMode);

    // If currently in a match or warfare, clear it first
    if (window.__dweebsToMenu) {
      window.__dweebsToMenu();
    }

    // Small delay to allow clean teardown before booting the new mode
    setTimeout(() => {
      if (window.__dweebsLaunchGame) {
        const arena = targetMode === 'adventure' ? 'meadowlands' : 'stadium';
        window.__dweebsLaunchGame(targetMode, arena);
      }
    }, 60);
  }

  toggleBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    setOpen(!isOpen);
  });

  menu.addEventListener('click', (e) => {
    const item = e.target.closest('.switcher-item');
    if (!item) return;
    const mode = item.dataset.mode;
    if (mode) executeSwitch(mode);
  });

  // Close on outside click
  document.addEventListener('click', (e) => {
    if (isOpen && !node.contains(e.target)) {
      setOpen(false);
    }
  });

  // Hotkey 'G' toggles switcher dropdown
  window.addEventListener('keydown', (e) => {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
    if (e.key === 'g' || e.key === 'G') {
      if (!e.ctrlKey && !e.metaKey && !e.altKey) {
        e.preventDefault();
        setOpen(!isOpen);
      }
    }
  });

  return {
    node,
    setMode,
    switchMode: executeSwitch,
    toggle: () => setOpen(!isOpen),
  };
}
