// HubBattleDiorama.js — 3D Low-Poly Action Diorama for Dweeb's Hub
//
// Implements 16 expressive low-poly 3D characters corresponding directly to the
// concept images in dweeb_images/, rendered together in a lively slow-motion
// cartoon skirmish in the background of the hub.

import * as THREE from 'three';
import { toonMat, noOutline, PALETTE } from './Toon.js';

function makeGooglyEye(radius = 0.14) {
  const eye = new THREE.Group();
  const sclera = new THREE.Mesh(
    new THREE.SphereGeometry(radius, 12, 10),
    toonMat({ color: 0xffffff })
  );
  const pupil = new THREE.Mesh(
    new THREE.SphereGeometry(radius * 0.48, 8, 8),
    toonMat({ color: 0x14101c })
  );
  pupil.position.z = radius * 0.72;
  eye.add(sclera);
  eye.add(pupil);
  eye.userData = { pupil, baseZ: radius * 0.72 };
  return eye;
}

export class HubBattleDiorama {
  constructor(scene) {
    this.scene = scene;
    this.group = new THREE.Group();
    this.group.name = 'HubBattleDiorama';
    this.group.scale.setScalar(1.25);
    this.scene.add(this.group);

    this.actors = [];
    this.clock = 0;
    this._buildActors();
  }

  _buildActors() {
    // 1. Blue Pyramid — sliding sideways fast
    {
      const root = new THREE.Group();
      const body = new THREE.Mesh(
        new THREE.ConeGeometry(0.55, 0.75, 4),
        toonMat({ color: 0x3fa9ff, flatShading: true })
      );
      body.rotation.y = Math.PI / 4;
      body.position.y = 0.38;
      root.add(body);

      const e1 = makeGooglyEye(0.11);
      e1.position.set(-0.14, 0.42, 0.26);
      const e2 = makeGooglyEye(0.12);
      e2.position.set(0.14, 0.44, 0.26);
      root.add(e1, e2);

      this.actors.push({
        root,
        eyes: [e1, e2],
        update: (t) => {
          // Surfing / sliding sideways across the front
          const slide = Math.sin(t * 1.4) * 4.5;
          root.position.set(slide - 1.5, 0.15, -4.5);
          root.rotation.z = -Math.cos(t * 1.4) * 0.25;
          root.rotation.y = Math.cos(t * 1.4) > 0 ? 0.3 : -0.3;
        },
      });
      this.group.add(root);
    }

    // 2. Yellow Cube Hopper & Spinner
    {
      const root = new THREE.Group();
      const body = new THREE.Mesh(
        new THREE.BoxGeometry(0.72, 0.72, 0.72),
        toonMat({ color: 0xffd23f, flatShading: true })
      );
      body.position.y = 0.4;
      root.add(body);

      const e1 = makeGooglyEye(0.14);
      e1.position.set(-0.16, 0.52, 0.38);
      const e2 = makeGooglyEye(0.13);
      e2.position.set(0.16, 0.54, 0.38);
      root.add(e1, e2);

      this.actors.push({
        root,
        eyes: [e1, e2],
        update: (t) => {
          const hop = Math.max(0, Math.sin(t * 3.2)) * 0.7;
          root.position.set(-3.8, hop + 0.1, -2.5);
          root.rotation.y = t * 2.5;
          root.rotation.z = Math.sin(t * 3.2) * 0.15;
        },
      });
      this.group.add(root);
    }

    // 3. Cyan Diamond / Octahedron Spinner
    {
      const root = new THREE.Group();
      const body = new THREE.Mesh(
        new THREE.OctahedronGeometry(0.48, 0),
        toonMat({ color: 0x2dd4bf, flatShading: true })
      );
      body.position.y = 0.52;
      root.add(body);

      const e1 = makeGooglyEye(0.12);
      e1.position.set(-0.13, 0.56, 0.32);
      const e2 = makeGooglyEye(0.11);
      e2.position.set(0.13, 0.54, 0.32);
      root.add(e1, e2);

      this.actors.push({
        root,
        eyes: [e1, e2],
        update: (t) => {
          root.position.set(3.6, 0.45 + Math.sin(t * 4) * 0.2, -3.2);
          root.rotation.y = t * 6.0;
          root.rotation.x = Math.sin(t * 2) * 0.2;
        },
      });
      this.group.add(root);
    }

    // 4. Golden Bouncing Sphere
    {
      const root = new THREE.Group();
      const body = new THREE.Mesh(
        new THREE.SphereGeometry(0.46, 16, 12),
        toonMat({ color: 0xf59e0b, flatShading: true })
      );
      body.position.y = 0.46;
      root.add(body);

      const e1 = makeGooglyEye(0.15);
      e1.position.set(-0.14, 0.54, 0.38);
      const e2 = makeGooglyEye(0.14);
      e2.position.set(0.16, 0.56, 0.38);
      root.add(e1, e2);

      this.actors.push({
        root,
        eyes: [e1, e2],
        update: (t) => {
          // Big squishy impact bounce
          const rawHop = Math.abs(Math.sin(t * 2.6));
          const y = rawHop * 1.8;
          root.position.set(0, y + 0.1, -6.5);
          const squash = rawHop < 0.15 ? 0.7 : 1.0 + rawHop * 0.2;
          body.scale.set(1 / Math.sqrt(squash), squash, 1 / Math.sqrt(squash));
        },
      });
      this.group.add(root);
    }

    // 5. Orange Torus / Donut Roller
    {
      const root = new THREE.Group();
      const body = new THREE.Mesh(
        new THREE.TorusGeometry(0.42, 0.16, 10, 24),
        toonMat({ color: 0xf97316, flatShading: true })
      );
      body.position.y = 0.55;
      root.add(body);

      const e1 = makeGooglyEye(0.11);
      e1.position.set(0, 0.72, 0.15);
      root.add(e1);

      this.actors.push({
        root,
        eyes: [e1],
        update: (t) => {
          // Rolling in a wide curved arc across the arena
          const angle = t * 0.9;
          const r = 5.8;
          root.position.set(Math.sin(angle) * r, 0.1, Math.cos(angle) * (r * 0.6) - 1.5);
          body.rotation.z = -t * 4.5;
          root.rotation.y = angle + Math.PI / 2;
        },
      });
      this.group.add(root);
    }

    // 6. Pink Impact Blob
    {
      const root = new THREE.Group();
      const body = new THREE.Mesh(
        new THREE.DodecahedronGeometry(0.48, 1),
        toonMat({ color: 0xff6fb5, flatShading: true })
      );
      body.position.y = 0.45;
      root.add(body);

      const e1 = makeGooglyEye(0.13);
      e1.position.set(-0.16, 0.52, 0.36);
      const e2 = makeGooglyEye(0.14);
      e2.position.set(0.15, 0.50, 0.36);
      root.add(e1, e2);

      this.actors.push({
        root,
        eyes: [e1, e2],
        update: (t) => {
          const hop = Math.max(0, Math.sin(t * 3.6 + 1.2)) * 0.6;
          root.position.set(-2.2, hop + 0.1, -1.2);
          root.rotation.y = Math.sin(t * 2) * 0.4 + 0.6;
        },
      });
      this.group.add(root);
    }

    // 7. Green Hopper with Peg Feet
    {
      const root = new THREE.Group();
      const body = new THREE.Mesh(
        new THREE.SphereGeometry(0.42, 14, 10),
        toonMat({ color: 0x22c55e, flatShading: true })
      );
      body.position.y = 0.46;
      root.add(body);

      const legMat = toonMat({ color: 0x15803d });
      const legL = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 0.24, 6), legMat);
      legL.position.set(-0.18, 0.12, 0);
      const legR = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 0.24, 6), legMat);
      legR.position.set(0.18, 0.12, 0);
      root.add(legL, legR);

      const e1 = makeGooglyEye(0.14);
      e1.position.set(-0.14, 0.54, 0.34);
      const e2 = makeGooglyEye(0.13);
      e2.position.set(0.14, 0.54, 0.34);
      root.add(e1, e2);

      this.actors.push({
        root,
        eyes: [e1, e2],
        update: (t) => {
          const hop = Math.max(0, Math.sin(t * 4.0)) * 0.45;
          root.position.set(2.4, hop + 0.1, -1.4);
          legL.rotation.x = Math.sin(t * 8) * 0.5;
          legR.rotation.x = -Math.sin(t * 8) * 0.5;
          root.rotation.y = -0.5 + Math.sin(t * 1.5) * 0.2;
        },
      });
      this.group.add(root);
    }

    // 8. Triangular Prism Zipper
    {
      const root = new THREE.Group();
      const body = new THREE.Mesh(
        new THREE.CylinderGeometry(0.42, 0.42, 0.65, 3),
        toonMat({ color: 0x8b5cf6, flatShading: true })
      );
      body.rotation.y = Math.PI / 6;
      body.position.y = 0.35;
      root.add(body);

      const e1 = makeGooglyEye(0.12);
      e1.position.set(-0.12, 0.42, 0.28);
      const e2 = makeGooglyEye(0.12);
      e2.position.set(0.12, 0.42, 0.28);
      root.add(e1, e2);

      this.actors.push({
        root,
        eyes: [e1, e2],
        update: (t) => {
          const zip = Math.sin(t * 2.2) * 3.2;
          root.position.set(zip + 1.2, 0.25, -5.2);
          root.rotation.y = Math.sin(t * 2.2) > 0 ? 0.8 : -0.8;
        },
      });
      this.group.add(root);
    }

    // 9. 5-Pointed Star Bouncer
    {
      const root = new THREE.Group();
      // Low-poly 5-pointed star via faceted cylinder
      const starGeo = new THREE.CylinderGeometry(0.52, 0.52, 0.24, 5);
      const body = new THREE.Mesh(
        starGeo,
        toonMat({ color: 0xf43f5e, flatShading: true })
      );
      body.rotation.x = Math.PI / 2;
      body.position.y = 0.52;
      root.add(body);

      const e1 = makeGooglyEye(0.13);
      e1.position.set(-0.14, 0.56, 0.16);
      const e2 = makeGooglyEye(0.13);
      e2.position.set(0.14, 0.56, 0.16);
      root.add(e1, e2);

      this.actors.push({
        root,
        eyes: [e1, e2],
        update: (t) => {
          // Slow-motion aerial backflips
          const hop = Math.abs(Math.sin(t * 1.8)) * 1.4;
          root.position.set(-4.5, hop + 0.3, -4.8);
          root.rotation.z = t * 2.2;
          root.rotation.y = Math.sin(t) * 0.4;
        },
      });
      this.group.add(root);
    }

    // 10. Aqua Spiky Cylinder
    {
      const root = new THREE.Group();
      const body = new THREE.Mesh(
        new THREE.CylinderGeometry(0.36, 0.36, 0.65, 8),
        toonMat({ color: 0x06b6d4, flatShading: true })
      );
      body.position.y = 0.42;
      root.add(body);

      // Add cute cone spikes
      const spikeMat = toonMat({ color: 0x0891b2, flatShading: true });
      for (let i = 0; i < 6; i++) {
        const spike = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.22, 5), spikeMat);
        const a = (i / 6) * Math.PI * 2;
        spike.position.set(Math.cos(a) * 0.38, 0.45, Math.sin(a) * 0.38);
        spike.rotation.z = -Math.cos(a) * 0.6;
        spike.rotation.x = Math.sin(a) * 0.6;
        root.add(spike);
      }

      const e1 = makeGooglyEye(0.13);
      e1.position.set(-0.14, 0.52, 0.36);
      const e2 = makeGooglyEye(0.13);
      e2.position.set(0.14, 0.52, 0.36);
      root.add(e1, e2);

      this.actors.push({
        root,
        eyes: [e1, e2],
        update: (t) => {
          const hop = Math.max(0, Math.sin(t * 3.5 + 0.5)) * 0.4;
          root.position.set(4.5, hop + 0.1, -4.2);
          root.rotation.y = Math.sin(t * 2) * 0.5 - 0.7;
        },
      });
      this.group.add(root);
    }

    // 11. Yellow Capsule Boxer (Fighting slowly with punches)
    {
      const root = new THREE.Group();
      const body = new THREE.Mesh(
        new THREE.CapsuleGeometry(0.3, 0.35, 6, 8),
        toonMat({ color: 0xfacc15, flatShading: true })
      );
      body.position.y = 0.48;
      root.add(body);

      const gloveMat = toonMat({ color: 0xef4444, flatShading: true });
      const gloveL = new THREE.Mesh(new THREE.SphereGeometry(0.16, 8, 8), gloveMat);
      gloveL.position.set(-0.42, 0.42, 0.3);
      const gloveR = new THREE.Mesh(new THREE.SphereGeometry(0.16, 8, 8), gloveMat);
      gloveR.position.set(0.42, 0.42, 0.3);
      root.add(gloveL, gloveR);

      const e1 = makeGooglyEye(0.12);
      e1.position.set(-0.12, 0.6, 0.28);
      const e2 = makeGooglyEye(0.12);
      e2.position.set(0.12, 0.6, 0.28);
      root.add(e1, e2);

      this.actors.push({
        root,
        eyes: [e1, e2],
        update: (t) => {
          // Slow-motion 1-2 punch combo sparring with the purple blob
          root.position.set(-0.9, 0.25, -2.2);
          root.rotation.y = 0.5;
          const punchL = Math.max(0, Math.sin(t * 4)) * 0.45;
          const punchR = Math.max(0, Math.sin(t * 4 + Math.PI)) * 0.45;
          gloveL.position.z = 0.25 + punchL;
          gloveR.position.z = 0.25 + punchR;
          root.position.y = 0.15 + Math.sin(t * 6) * 0.05;
        },
      });
      this.group.add(root);
    }

    // 12. Purple Sparring Partner (Dodging & parrying)
    {
      const root = new THREE.Group();
      const body = new THREE.Mesh(
        new THREE.DodecahedronGeometry(0.42, 0),
        toonMat({ color: 0xa855f7, flatShading: true })
      );
      body.position.y = 0.45;
      root.add(body);

      const e1 = makeGooglyEye(0.13);
      e1.position.set(-0.13, 0.52, 0.32);
      const e2 = makeGooglyEye(0.14);
      e2.position.set(0.13, 0.52, 0.32);
      root.add(e1, e2);

      this.actors.push({
        root,
        eyes: [e1, e2],
        update: (t) => {
          // Bobbing & weaving against the boxer
          const lean = Math.sin(t * 4) * 0.3;
          root.position.set(0.6 + lean * 0.5, 0.2, -2.1);
          root.rotation.y = -2.6;
          root.rotation.z = -lean * 0.4;
        },
      });
      this.group.add(root);
    }

    // 13. Teal Aerial Martial Arts Flipper
    {
      const root = new THREE.Group();
      const body = new THREE.Mesh(
        new THREE.CylinderGeometry(0.28, 0.28, 0.6, 6),
        toonMat({ color: 0x14b8a6, flatShading: true })
      );
      body.position.y = 0.35;
      root.add(body);

      const e1 = makeGooglyEye(0.11);
      e1.position.set(-0.11, 0.44, 0.24);
      const e2 = makeGooglyEye(0.11);
      e2.position.set(0.11, 0.44, 0.24);
      root.add(e1, e2);

      this.actors.push({
        root,
        eyes: [e1, e2],
        update: (t) => {
          // Somersaulting high in the air
          const flight = Math.sin(t * 1.5);
          root.position.set(2.8, 1.8 + flight * 0.7, -5.8);
          root.rotation.x = t * 2.8;
          root.rotation.y = t * 1.2;
        },
      });
      this.group.add(root);
    }

    // 14. Violet Stalky with Periscope Eyes
    {
      const root = new THREE.Group();
      const body = new THREE.Mesh(
        new THREE.SphereGeometry(0.38, 12, 10),
        toonMat({ color: 0x7c3aed, flatShading: true })
      );
      body.position.y = 0.4;
      root.add(body);

      // Periscope stalks
      const stalkMat = toonMat({ color: 0x6d28d9 });
      const sL = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 0.4, 6), stalkMat);
      sL.position.set(-0.18, 0.72, 0.05);
      const sR = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 0.36, 6), stalkMat);
      sR.position.set(0.18, 0.7, 0.05);
      root.add(sL, sR);

      const e1 = makeGooglyEye(0.12);
      e1.position.set(-0.18, 0.92, 0.08);
      const e2 = makeGooglyEye(0.11);
      e2.position.set(0.18, 0.88, 0.08);
      root.add(e1, e2);

      this.actors.push({
        root,
        eyes: [e1, e2],
        update: (t) => {
          const hop = Math.max(0, Math.sin(t * 2.5 + 2.0)) * 0.5;
          root.position.set(-5.6, hop + 0.1, -3.2);
          sL.rotation.z = Math.sin(t * 3) * 0.2;
          sR.rotation.z = -Math.sin(t * 3.5) * 0.2;
        },
      });
      this.group.add(root);
    }
  }

  setVisible(visible) {
    this.group.visible = visible;
  }

  update(dt) {
    if (!this.group.visible) return;
    this.clock += dt;
    const t = this.clock;
    for (let i = 0; i < this.actors.length; i++) {
      const a = this.actors[i];
      a.update(t);

      // Cute eye look-around movement
      for (const eye of a.eyes) {
        if (eye.userData?.pupil) {
          eye.userData.pupil.position.x = Math.sin(t * 2.5 + i) * 0.03;
          eye.userData.pupil.position.y = Math.cos(t * 1.8 + i) * 0.03;
        }
      }
    }
  }

  dispose() {
    this.scene.remove(this.group);
  }
}
